  testWidgets('shop filters real catalog items and clears both search and category', (tester) async {
    tester.view.physicalSize = const Size(320, 900);tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);addTearDown(tester.view.resetDevicePixelRatio);
    fixtureProducts.addAll([
      {'id': 'coat', 'name': 'Lab coat', 'category': 'Lab essentials', 'price': 1200, 'stockCount': 3},
      {'id': 'gloves', 'name': 'Lab gloves', 'category': 'Lab essentials', 'price': 300, 'stockStatus': 'out_of_stock'},
    ]);
    await open(tester, '/shop');
    expect(find.text('2 products in the catalog'), findsOneWidget);
    final search = find.byWidgetPredicate((w) => w is TextField && w.decoration?.hintText == 'Search products');
    await tester.ensureVisible(search);await tester.enterText(search, 'unmatched term');
    await tester.pump(const Duration(milliseconds: 300));await tester.pumpAndSettle();
    expect(find.text('No matching products'), findsOneWidget);
    await tester.ensureVisible(find.text('Clear filters'));await tester.tap(find.text('Clear filters'));await tester.pumpAndSettle();
    expect((tester.widget<TextField>(find.byWidgetPredicate((w) => w is TextField && w.decoration?.hintText == 'Search products')).controller!).text, '');
    await tester.scrollUntilVisible(find.text('Lab gloves'), 200, scrollable: find.byType(Scrollable).first);
    expect(find.text('Out of stock'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
