        }
        admin.read(themeModeProvider.notifier).set(ThemeMode.system);
        await tester.pumpAndSettle();
      }
    }
    expect(find.text('2nd Professional'), findsOneWidget);
  });

  testWidgets('Study mixed folders preserve deep links and navigate recursive children', (tester) async {
    final year=fixtureTree.first;
    final semester=(year['semesters'] as List).first as Map;
    final subject=(semester['subjects'] as List).first as Map;
    final section=(subject['sections'] as List).first as Map;
    final topic=(section['topics'] as List).first as Map;
    topic['folders']=[{'id':'extra','title':'Extra folder','files':[
      {'id':'extra-file','title':'Reference PDF','pdfUrl':'https://example.org/reference.pdf','published':true},
    ]}];
    await open(tester,'/study/notes/id-0/id-1/id-2/id-3/id-4');
    expect(find.text('Insulin Notes'),findsOneWidget);
    expect(find.text('Extra folder'),findsOneWidget);
    await tester.tap(find.text('Extra folder')); await tester.pumpAndSettle();
    expect(find.text('Reference PDF'),findsOneWidget);
    expect(GoRouterState.of(tester.element(find.text('Reference PDF'))).uri.queryParametersAll['folder'],['extra']);
    expect(find.text('Load preview'),findsOneWidget);
  });
  if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
    testWidgets('representative screens visual QA', (tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      for (final mode in [ThemeMode.dark, ThemeMode.light]) {
        await tester.pumpWidget(const SizedBox.shrink());
        await tester.pumpAndSettle();
        container.read(themeModeProvider.notifier).set(mode);
        for (final path in [
          '/home',
          '/study',
          '/pdf-studio',
          '/study/notes/id-0/id-1/id-2/id-3/id-4',
          '/downloads',
          '/profile',
          '/profile/edit',
          '/contact',
          '/shop',
          '/blog',
          '/settings',
          '/about',
        ]) {
          await open(tester, path);
          await tester.runAsync(
            () => Future<void>.delayed(const Duration(milliseconds: 60)),
          );
          await tester.pump(const Duration(milliseconds: 500));
          await tester.runAsync(
            () => Future<void>.delayed(const Duration(milliseconds: 120)),
          );
          await tester.pump();
          await expectLater(
            find.byType(HyzenApp),
            matchesGoldenFile(
              '../qa/${mode.name}${path.replaceAll('/', '_')}.png',
            ),
          );
          expect(tester.takeException(), isNull);
        }
      }
    });
  }
  testWidgets('saved checkout restores original contact and total with an empty cart', (tester) async {
    final cart = [CartItem(productId: 'fixture', name: 'Saved book', qty: 2, price: 100)];
    final order = buildOrder(cart: cart, f: CheckoutForm(firstName: 'Saved', lastName: 'Student',
      phone: '+923009999999', phoneSecondary: '', line1: 'Fixture road', city: 'Karachi',
      province: 'Sindh', deliveryAddress: '', notes: ''), email: 'student@example.org',
      delivery: DeliverySettings.fromRaw({}), orderNumber: 'PW-2026-123456');
    await tester.runAsync(() => PendingCheckoutStore('student-test').stage(order, cart));
    await open(tester, '/checkout');
    expect(find.text('Order PW-2026-123456'), findsOneWidget);
    expect(find.text('Saved'), findsOneWidget);
    expect(tester.widgetList<TextField>(find.byType(TextField)).every((f) => f.readOnly), true);
    await tester.scrollUntilVisible(find.text('Retry original order'), 300, scrollable: find.byType(Scrollable).first);
    expect(find.text('Retry original order'), findsOneWidget);
    if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
      await expectLater(find.byType(HyzenApp), matchesGoldenFile('../qa/checkout_recovery.png'));
    }
    expect(tester.takeException(), isNull);
  });
  testWidgets('acknowledged saved checkout finishes locally without resubmitting', (tester) async {
    final store = PendingCheckoutStore('student-test');
    final cart = [CartItem(productId: 'fixture', name: 'Saved book', qty: 1, price: 100)];
    final order = buildOrder(cart: cart, f: CheckoutForm(firstName: 'Saved', lastName: 'Student',
      phone: '+923009999999', phoneSecondary: '', line1: 'Fixture road', city: 'Lahore',
      province: 'Punjab', deliveryAddress: '', notes: ''), email: 'student@example.org',
      delivery: DeliverySettings.fromRaw({}), orderNumber: 'PW-2026-123456');
    await tester.runAsync(() async => store.acknowledge(await store.stage(order, cart)));
    await open(tester, '/cart');
    expect(find.text('Resume saved checkout'), findsOneWidget);
    await tester.tap(find.text('Resume saved checkout'));
    await tester.pumpAndSettle();
    await tester.scrollUntilVisible(find.text('Retry original order'), 300, scrollable: find.byType(Scrollable).first);
    await tester.runAsync(() async {
      await tester.tap(find.text('Retry original order'));
      for (var i = 0; i < 100 && store.exists; i++) {
        await Future<void>.delayed(const Duration(milliseconds: 10));
      }
    });
    await tester.pumpAndSettle();
    expect(find.byType(OrderSuccessScreen), findsOneWidget);
    expect(store.read(), isNull);
    expect(container.read(myOrdersProvider).single['id'], order['id']);
    expect(tester.takeException(), isNull);
  });

}

