class CheckoutScreen extends ConsumerStatefulWidget {
  const CheckoutScreen({super.key});
  @override
  ConsumerState<CheckoutScreen> createState() => _CheckoutScreenState();
}

class _CheckoutScreenState extends ConsumerState<CheckoutScreen> {
  final _form = GlobalKey<FormState>();
  final _c = {
    for (final k in [
      'first',
      'last',
      'phone',
      'phone2',
      'line1',
      'city',
      'deliv',
      'notes',
    ])
      k: TextEditingController(),
  };
  String _province = 'Punjab';
  bool _busy = false;
  late final String _orderNo = newOrderNumber();
  Map<String, dynamic>? _pendingOrder;
  Map<String, dynamic>? _pendingRecord;
  List<CartItem> _pendingCart = [];
  late final String _checkoutUid;
  late final PendingCheckoutStore _journal;
  String? _recoveryError;

  void _restore(Map<String, dynamic> record) {
    _pendingRecord = record;
    _pendingOrder = (record['order'] as Map).cast<String, dynamic>();
    _pendingCart = (record['cart'] as List).whereType<Map>()
        .map((m) => CartItem.fromMap(m.cast<String, dynamic>()))
        .whereType<CartItem>().toList();
    final customer = _pendingOrder!['customer'] as Map;
    final address = _pendingOrder!['address'] as Map;
    for (final entry in {'first': customer['firstName'], 'last': customer['lastName'],
      'phone': customer['phone'], 'phone2': customer['phoneSecondary'],
      'line1': address['line1'], 'city': address['city'],
      'deliv': address['deliveryAddress'], 'notes': address['notes']}.entries) {
      _c[entry.key]!.text = entry.value is String ? entry.value as String : '';
    }
    _province = address['province'] as String? ?? 'Punjab';
  }

  @override
  void initState() {
    super.initState();
    _checkoutUid = ref.read(authStateProvider).valueOrNull?.uid ?? 'guest';
    _journal = PendingCheckoutStore(_checkoutUid);
    try {
      final pending = _journal.read();
      if (pending != null) { _restore(pending); return; }
    } on FriendlyException catch (e) { _recoveryError = e.message; }
    final p = ref.read(profileProvider).valueOrNull;
    if (p != null) {
      final parts = p.fullName.trim().split(RegExp(r'\s+'));
      _c['first']!.text = parts.first;
      _c['last']!.text = parts.length > 1 ? parts.sublist(1).join(' ') : '';
      _c['phone']!.text = p.mobile;
      _c['city']!.text = p.city;
    }
  }

  @override
  void dispose() {
    for (final c in _c.values) {
      c.dispose();
    }
    super.dispose();
  }

  Future<void> _place() async {
    if (_busy || _recoveryError != null) return;
    if ((ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') != _checkoutUid) {
      showHSnack(context, 'Account changed. Reopen checkout to continue.', error: true);
      return;
    }
    if (_pendingOrder == null && !_form.currentState!.validate()) return;
    final cart = ref.read(cartProvider);
    if (cart.isEmpty && _pendingOrder == null) return;
    // CONFIRMED: re-validate stock right before committing.
    final products =
        ref.read(productsProvider).valueOrNull?.data ?? const <Product>[];
    final wanted = <String, int>{};
    for (final i in cart) {
      wanted[i.productId] = (wanted[i.productId] ?? 0) + i.qty;
    }
    for (final e in _pendingOrder == null ? wanted.entries : <MapEntry<String, int>>[]) {
      final p = products.where((x) => x.id == e.key).firstOrNull;
      if (p == null) {
        return showHSnack(
          context,
          'An item in your cart is no longer available',
          error: true,
        );
      }
      if (p.availStock <= 0) {
        return showHSnack(
          context,
          '"${p.name}" just went out of stock',
          error: true,
        );
      }
      if (e.value > p.availStock) {
        return showHSnack(
          context,
          'Only ${p.availStock} of "${p.name}" left \u2014 please adjust your cart',
          error: true,
        );
      }
    }
    setState(() => _busy = true);
    if (_pendingOrder == null) _pendingCart = List.of(cart);
    final order = _pendingOrder ??= buildOrder(
      cart: cart,
      f: CheckoutForm(
        firstName: _c['first']!.text,
        lastName: _c['last']!.text,
        phone: _c['phone']!.text,
        phoneSecondary: _c['phone2']!.text,
        line1: _c['line1']!.text,
        city: _c['city']!.text,
        province: _province,
        deliveryAddress: _c['deliv']!.text,
        notes: _c['notes']!.text,
      ),
      email: ref.read(authStateProvider).valueOrNull?.email ?? '',
      delivery: ref.read(deliveryProvider),
      orderNumber: _orderNo,
    );
    try {
      // No network write until the original payload is durably recoverable.
      final record = await _journal.stage(order, _pendingCart);
      if (!mounted) return;
      setState(() => _restore(record));
      if ((ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') != _checkoutUid) return;
      final original = _pendingOrder!;
      if (_pendingRecord?['acknowledged'] != true) {
        await ref.read(ordersRepositoryProvider).submit(original);
        await _journal.acknowledge(record);
        _pendingRecord = {...record, 'acknowledged': true};
      }
      if (!mounted || (ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') != _checkoutUid) return;
      final history = ref.read(myOrdersProvider.notifier);
      final cartController = ref.read(cartProvider.notifier);
      final saved = await finishAcknowledgedOrder(
        saveHistory: () => history.add(original),
        clearCart: () async {
          if (!mounted || (ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') != _checkoutUid) {
            throw StateError('Account changed during checkout cleanup');
          }
          await cartController.completeOrder(original['id'] as String, _pendingCart);
        },
      );
      if (saved) await _journal.clear();
      if (mounted && (ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') == _checkoutUid && !saved) showHSnack(context,
          'Order sent. Device cleanup is pending; keep order ${original['orderNumber']}.');
      if (mounted && (ref.read(authStateProvider).valueOrNull?.uid ?? 'guest') == _checkoutUid) {
        context.pushReplacement('/order-success', extra: original);
      }
    } on FriendlyException catch (e) {
      if (mounted) showHSnack(context, e.message, error: true);
    } catch (_) {
      if (mounted) showHSnack(context,
          'Checkout recovery could not be saved on this device. Free some storage and retry this same order.', error: true);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final t = Theme.of(context);
    final currentCart = ref.watch(cartProvider);
    final cart = _pendingOrder == null ? currentCart : _pendingCart;
    final d = ref.watch(deliveryProvider);
    final totals = _pendingOrder?['totals'] as Map?;
    final sub = totals?['subtotal'] as num? ?? cart.fold<num>(0, (s, i) => s + i.price * i.qty);
    final del = totals?['delivery'] as num? ?? d.chargeFor(sub, _province);
    InputDecoration dec(String l, {String? hint}) =>
        InputDecoration(labelText: l, hintText: hint);
    return Scaffold(
      extendBodyBehindAppBar: true,
      appBar: HTopBar(title: 'Checkout', subtitle: 'Order ${_pendingOrder?['orderNumber'] ?? _orderNo}'),
      body: HBackground(
        child: Form(
          key: _form,
          child: ListView(
            padding: EdgeInsets.fromLTRB(
              HSpace.screen,
              MediaQuery.paddingOf(context).top + 76,
              HSpace.screen,
              HSpace.xxl,
            ),
            children: [
              PanelBlock(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Contact', style: t.textTheme.titleMedium),
                    const Gap(HSpace.md),
                    Row(
                      children: [
                        Expanded(
                          child: TextFormField(
                      readOnly: _pendingOrder != null,
                            controller: _c['first'],
                            decoration: dec('First name'),
                            validator: (v) =>
                                Validators.required(v, 'First name'),
                          ),
                        ),
                        const SizedBox(width: HSpace.sm),
                        Expanded(
                          child: TextFormField(
                      readOnly: _pendingOrder != null,
                            controller: _c['last'],
                            decoration: dec('Last name'),
                            validator: (v) =>
                                Validators.required(v, 'Last name'),
                          ),
                        ),
                      ],
                    ),
                    const Gap(HSpace.md),
                    TextFormField(
                      readOnly: _pendingOrder != null,
                      controller: _c['phone'],
                      keyboardType: TextInputType.phone,
                      decoration: dec('Phone', hint: '+923001234567'),
                      validator: Validators.phone,
                    ),
                    const Gap(HSpace.md),
                    TextFormField(
                      readOnly: _pendingOrder != null,
                      controller: _c['phone2'],
                      keyboardType: TextInputType.phone,
                      decoration: dec('Secondary phone (optional)'),
                    ),
                  ],
                ),
              ),
              const Gap(HSpace.md),
              PanelBlock(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Delivery address', style: t.textTheme.titleMedium),
                    const Gap(HSpace.md),
                    TextFormField(
                      readOnly: _pendingOrder != null,
                      controller: _c['line1'],
                      decoration: dec('Address'),
                      validator: (v) => Validators.required(v, 'Address'),
                    ),
                    const Gap(HSpace.md),
                    TextFormField(
                      readOnly: _pendingOrder != null,
                      controller: _c['city'],
                      decoration: dec('City'),
                      validator: (v) => Validators.required(v, 'City'),
                    ),
                    const Gap(HSpace.md),
                    DropdownButtonFormField<String>(
                      initialValue: _province,
                      decoration: dec('Province'),
                      items: DeliverySettings.provinces
                          .map(
                            (p) => DropdownMenuItem(value: p, child: Text(p)),
                          )
                          .toList(),
                      onChanged: _pendingOrder != null ? null : (v) =>
                          setState(() => _province = v ?? _province),
                    ),
                    const Gap(HSpace.md),
                    TextFormField(
                      readOnly: _pendingOrder != null,
                      controller: _c['deliv'],
                      decoration: dec(
                        'Delivery instructions',
