    final orders = ref.watch(myOrdersProvider);
    Future<void> sync() async {
      final repo = ref.read(ordersRepositoryProvider);
      for (final o in orders) {
        try {
          final v = await repo.verification('${o['verifyToken']}');
          if (v != null) {
