/// CONFIRMED legacy cart item `{productId,name,qty,price,variant}` (device-local, pw_cart).
class CartItem {
  CartItem({
    required this.productId,
    required this.name,
    required this.qty,
    required this.price,
    this.variant = '',
  });
  final String productId;
  final String name;
  final int qty;
  final num price;
  final String variant;
  String get key => '$productId|$variant';
  Map<String, dynamic> toMap() => {
    'productId': productId,
    'name': name,
    'qty': qty,
    'price': price,
    'variant': variant,
  };
  static CartItem? fromMap(Map<String, dynamic> m) {
    final id = m['productId'];
    if (id is! String) return null;
    return CartItem(
      productId: id,
      name: (m['name'] as String?) ?? '',
      qty: (m['qty'] as num?)?.toInt() ?? 1,
      price: (m['price'] as num?) ?? 0,
      variant: (m['variant'] as String?) ?? '',
    );
  }

  CartItem withQty(int q) => CartItem(
    productId: productId,
    name: name,
    qty: q,
    price: price,
    variant: variant,
  );
}

class CartController extends Notifier<List<CartItem>> {
  String get _k =>
      'items_${ref.read(authStateProvider).valueOrNull?.uid ?? 'guest'}';
  JsonBox get _box => JsonBox(Boxes.cart);

  @override
  List<CartItem> build() {
    ref.watch(authStateProvider.select((v) => v.valueOrNull?.uid));
    final m = JsonBox(Boxes.cart).get(_k);
    final l = m?['items'];
    if (l is! List) return [];
    return l
        .whereType<Map>()
        .map((e) => CartItem.fromMap(e.cast<String, dynamic>()))
        .whereType<CartItem>()
        .toList();
  }

  void _save(List<CartItem> l) {
    state = l;
    _box.put(_k, {...?_box.get(_k), 'items': l.map((e) => e.toMap()).toList()});
  }

  /// Returns an error message when stock would be exceeded (legacy availStock guard).
  String? add(Product p, {int qty = 1, String variant = ''}) {
    if (qty < 1) return 'Choose a quantity greater than zero';
    final inCart = state
        .where((i) => i.productId == p.id)
        .fold(0, (s, i) => s + i.qty);
    final avail = p.availStock;
    if (avail <= 0) return '"${p.name}" is out of stock';
    if (inCart + qty > avail) return 'Only $avail of "${p.name}" available';
    final l = [...state];
    final i = l.indexWhere((x) => x.productId == p.id && x.variant == variant);
    if (i >= 0) {
      l[i] = l[i].withQty(l[i].qty + qty);
    } else {
      l.add(
        CartItem(
          productId: p.id,
          name: p.name,
          qty: qty,
          price: p.price,
          variant: variant,
        ),
      );
    }
    _save(l);
    return null;
  }

  void setQty(CartItem it, int q) {
    _save(
      state.map((x) => x.key == it.key ? x.withQty(max(1, q)) : x).toList(),
    );
  }

  void remove(CartItem it) =>
      _save(state.where((x) => x.key != it.key).toList());
  void clear() => _save([]);

  /// The completion marker and remaining cart share one durable record. A retry
  /// after a crash must not subtract purchased quantities from a newer cart twice.
  Future<void> completeOrder(String id, List<CartItem> purchased) async {
    final key = _k;
    final current = _box.get(key);
    if (current?['completedOrderId'] == id) return;
    final remaining = cartAfterPurchase(state, purchased);
    await _box.put(key, {'items': remaining.map((i) => i.toMap()).toList(),
      'completedOrderId': id});
    if (_k == key) state = remaining;
  }

  num get subtotal => state.fold<num>(0, (s, i) => s + i.price * i.qty);
  int get count => state.fold(0, (s, i) => s + i.qty);
}

final cartProvider = NotifierProvider<CartController, List<CartItem>>(
  CartController.new,
);
final cartCountProvider = Provider<int>(
  (ref) => ref.watch(cartProvider).fold(0, (s, i) => s + i.qty),
);

List<CartItem> cartAfterPurchase(List<CartItem> current, List<CartItem> purchased) {
  final quantities = <String, int>{};
  for (final item in purchased) {
    quantities[item.key] = (quantities[item.key] ?? 0) + item.qty;
  }
  return [for (final item in current)
    if (item.qty > (quantities[item.key] ?? 0))
      item.withQty(item.qty - (quantities[item.key] ?? 0))];
}

/// Device-local outbox scoped to the signed-in account. Save before any request;
/// keep the same ID and bearer token until acknowledgement and cleanup finish.
class PendingCheckoutStore {
  PendingCheckoutStore(this.uid);
  final String uid;
  String get _key => 'pending_checkout_$uid';
  JsonBox get _box => JsonBox(Boxes.cart);
  bool get exists => _box.keys.contains(_key);
  Map<String, dynamic>? read() {
    final value = _box.get(_key);
    if (value == null && !exists) return null;
    final order = value?['order'];
    if (order is! Map || order['id'] is! String || order['verifyToken'] is! String ||
        order['orderNumber'] is! String || order['items'] is! List ||
        order['customer'] is! Map || order['address'] is! Map ||
        order['totals'] is! Map || value?['cart'] is! List) {
      throw FriendlyException('Saved checkout could not be read. Contact support before placing another order.');
    }
    final totals = order['totals'] as Map;
    final address = order['address'] as Map;
    final cart = value!['cart'] as List;
    if (['subtotal','delivery','grandTotal'].any((key) => totals[key] is! num ||
          !(totals[key] as num).isFinite || (totals[key] as num) < 0) ||
        (address['province'] != null && (address['province'] is! String ||
          !DeliverySettings.provinces.contains(address['province']))) ||
        cart.any((item) => item is! Map || item['productId'] is! String ||
          item['name'] is! String || item['qty'] is! int || item['qty'] < 1 ||
          item['price'] is! num || !(item['price'] as num).isFinite || item['price'] < 0 ||
          (item['variant'] != null && item['variant'] is! String))) {
      throw FriendlyException('Saved checkout could not be read. Contact support before placing another order.');
    }
    return value;
  }
  Future<Map<String, dynamic>> stage(Map<String, dynamic> order, List<CartItem> cart) async {
    final existing = read();
    if (existing != null) return existing;
    final value = <String, dynamic>{'order': order,
      'cart': cart.map((i) => i.toMap()).toList(), 'acknowledged': false};
    await _box.put(_key, value);
    return value;
  }
  Future<void> acknowledge(Map<String, dynamic> value) =>
      _box.put(_key, {...value, 'acknowledged': true});
  Future<void> clear() => _box.delete(_key);
}

// ---------------- Orders ----------------
final _rnd = Random.secure();

/// CONFIRMED `"PW-"+year+"-"+(100000..999999)`.
String newOrderNumber([DateTime? now]) =>
    'PW-${(now ?? DateTime.now()).year}-${_rnd.nextInt(900000) + 100000}';

/// CONFIRMED legacy `uid(p)` = p + "-" + 6 base36 chars.
String legacyUid(String prefix) {
  const a = '0123456789abcdefghijklmnopqrstuvwxyz';
  return '$prefix-${List.generate(6, (_) => a[_rnd.nextInt(36)]).join()}';
}

/// CONFIRMED `verifyToken()` = "v_" + 32 hex (128-bit).
String newVerifyToken() =>
    'v_${List.generate(16, (_) => _rnd.nextInt(256).toRadixString(16).padLeft(2, '0')).join()}';

class CheckoutForm {
  CheckoutForm({
    required this.firstName,
    required this.lastName,
    required this.phone,
    required this.phoneSecondary,
    required this.line1,
    required this.city,
    required this.province,
    required this.deliveryAddress,
    required this.notes,
  });
  final String firstName,
      lastName,
      phone,
      phoneSecondary,
      line1,
      city,
      province,
      deliveryAddress,
      notes;
}

/// Builds the exact legacy order object (placeOrder in v2).
Map<String, dynamic> buildOrder({
  required List<CartItem> cart,
  required CheckoutForm f,
  required String email,
  required DeliverySettings delivery,
  required String orderNumber,
  DateTime? now,
}) {
  final sub = cart.fold<num>(0, (s, i) => s + i.price * i.qty);
  final del = delivery.chargeFor(sub, f.province);
  return {
    'id': legacyUid('ord'),
    'orderNumber': orderNumber,
    'verifyToken': newVerifyToken(),
    'items': cart
        .map(
          (i) => {
            'productId': i.productId,
            'name': i.name + (i.variant.isNotEmpty ? ' (${i.variant})' : ''),
            'qty': i.qty,
            'price': i.price,
          },
        )
        .toList(),
    'customer': {
      'firstName': f.firstName.trim(),
      'lastName': f.lastName.trim(),
      'phone': f.phone.trim(),
      'phoneSecondary': f.phoneSecondary.trim(),
      'email': email,
    },
    'address': {
      'line1': f.line1.trim(),
      'city': f.city.trim(),
      'province': f.province,
      'deliveryAddress': f.deliveryAddress.trim(),
      'notes': f.notes.trim(),
    },
    'totals': {'subtotal': sub, 'delivery': del, 'grandTotal': sub + del},
    'status': 'Pending',
    'payment': 'Unpaid',
    'createdAt': (now ?? DateTime.now()).toUtc().toIso8601String(),
  };
}

/// Public bearer-link status only. Full checkout data remains in private order storage.
/// Never spread an order/customer map into this response.
Map<String, dynamic> verificationSnapshot(Map<String, dynamic> order) {
  String text(String key, int limit) {
    final value = order[key];
    if (value is! String) return '';
    final cleaned = value.trim();
    return cleaned.length <= limit ? cleaned : '';
  }
  final number = text('orderNumber', 40);
  final created = DateTime.tryParse(text('createdAt', 64));
  const statuses = ['Pending', 'Processing', 'Paid', 'Completed', 'Cancelled',
    'Refunded', 'Confirmed', 'Accepted', 'Packed', 'Shipped', 'Delivered', 'Rejected'];
  const payments = ['Unpaid', 'Paid', 'Refunded', 'Partially paid'];
  final status = text('status', 40), payment = text('payment', 40);
  return {
    'orderNumber': RegExp(r'^PW-[0-9]{4}-[0-9]{6}$').hasMatch(number) ? number : '',
    'status': statuses.contains(status) ? status : 'Pending',
    'payment': payments.contains(payment) ? payment : 'Unpaid',
    'createdAt': created?.toUtc().toIso8601String() ?? '',
    'trackingId': text('trackingId', 100),
  };
}

class OrdersRepository {
  OrdersRepository(this._db);
  final FirebaseFirestore _db;

  /// CONFIRMED Cloud.submitOrder: orders_inbox/{id} {value, createdAt:ms} + verifications/{token}.
  Future<void> submit(Map<String, dynamic> o) async {
    await submitOrderAttempt(o, writeAtomic: () async {
      final receiptRef = _db.collection('verifications').doc(o['verifyToken'] as String);
      await _db.runTransaction((tx) async {
        final receipt = await tx.get(receiptRef);
        if (receipt.exists) {
          if (receiptMatchesOrder(o, receipt.data())) return;
          throw FriendlyException('This order reference needs support review.');
        }
        tx.set(_db.collection('orders_inbox').doc(o['id'] as String),
            {'value': o, 'createdAt': DateTime.now().millisecondsSinceEpoch});
        tx.set(receiptRef, verificationSnapshot(o));
      }).timeout(const Duration(seconds: 20));
    }, readReceipt: () async => (await _db.collection('verifications')
        .doc(o['verifyToken'] as String)
        .get(const GetOptions(source: Source.server))
        .timeout(const Duration(seconds: 5))).data());
  }

  /// Public masked status lookup (CONFIRMED: verifications are public get).
  Future<Map<String, dynamic>?> verification(String token) async {
    final s = await _db.collection('verifications').doc(token).get();
    return s.data();
  }
}

bool receiptMatchesOrder(Map<String, dynamic> order, Map<String, dynamic>? receipt) {
  final expected = verificationSnapshot(order);
  return expected['orderNumber'] != '' && expected['createdAt'] != '' &&
      receipt?['orderNumber'] == expected['orderNumber'] &&
      receipt?['createdAt'] == expected['createdAt'];
}

/// Reuses the original random token after a lost acknowledgement. This receipt
/// is for retry recovery only, never proof of payment or accepted stock.
Future<void> submitOrderAttempt(Map<String, dynamic> order, {
  required Future<void> Function() writeAtomic,
  required Future<Map<String, dynamic>?> Function() readReceipt,
}) async {
  try {
    await writeAtomic();
    return;
  } catch (_) {
    try {
      final receipt = await readReceipt();
      if (receiptMatchesOrder(order, receipt)) return;
    } catch (_) { /* An unavailable lookup cannot confirm a submission. */ }
    throw FriendlyException('Order confirmation is unavailable. Retry this same checkout; do not start a second order.');
  }
}

/// Once acknowledged, a device-storage failure must not offer to resubmit.
Future<bool> finishAcknowledgedOrder({
  required Future<void> Function() saveHistory,
  required Future<void> Function() clearCart,
}) async {
  var saved = true;
  try { await saveHistory(); } catch (_) { saved = false; }
  try { await clearCart(); } catch (_) { saved = false; }
  return saved;
}

final ordersRepositoryProvider = Provider<OrdersRepository>(
  (ref) => OrdersRepository(ref.watch(firestoreProvider)),
);

/// Orders placed on this device (legacy also kept a local copy).
class MyOrdersController extends Notifier<List<Map<String, dynamic>>> {
  JsonBox get _box => JsonBox(Boxes.myOrders);
  @override
  List<Map<String, dynamic>> build() {
    final user = ref.watch(authStateProvider).valueOrNull;
    final l =
        JsonBox(Boxes.myOrders)
            .values()
            .where(
              (o) =>
                  o['ownerUid'] == user?.uid ||
                  (o['ownerUid'] == null &&
                      (o['customer'] as Map?)?['email'] == user?.email),
            )
            .toList()
          ..sort((a, b) => '${b['createdAt']}'.compareTo('${a['createdAt']}'));
    return l;
  }

  Future<void> add(Map<String, dynamic> o) async {
    final local = {
      ...o,
      'ownerUid': ref.read(authStateProvider).valueOrNull?.uid,
    };
    state = [local, ...state.where((v) => v['id'] != o['id'])];
    await _box.put(o['id'] as String, local);
  }

  Future<void> updateStatus(String id, Map<String, dynamic> v) async {
    final i = state.indexWhere((o) => o['id'] == id);
    if (i < 0) return;
    final o = {
      ...state[i],
      'status': v['status'] ?? state[i]['status'],
      'payment': v['payment'] ?? state[i]['payment'],
      'trackingId': v['trackingId'] ?? state[i]['trackingId'],
    };
    await _box.put(id, o);
    state = [...state]..[i] = o;
  }
}

final myOrdersProvider =
    NotifierProvider<MyOrdersController, List<Map<String, dynamic>>>(
      MyOrdersController.new,
    );

// ---------------- Contact ----------------
/// CONFIRMED sendMessage: `{id:"msg-xxxxxx",name,email,whatsapp,subject,body,read:false,createdAt}`
/// → messages_inbox/{id} `{value, createdAt:ms}` (create-only).
Future<void> submitContactMessage(
  FirebaseFirestore db, {
  required String name,
  required String email,
  required String whatsapp,
  required String subject,
  required String body,
}) async {
  final m = {
    'id': legacyUid('msg'),
    'name': name.trim(),
    'email': email.trim(),
    'whatsapp': whatsapp.trim(),
    'subject': subject.trim(),
    'body': body.trim(),
    'read': false,
    'createdAt': DateTime.now().toUtc().toIso8601String(),
  };
  try {
    await db
        .collection('messages_inbox')
        .doc(m['id'] as String)
        .set({'value': m, 'createdAt': DateTime.now().millisecondsSinceEpoch})
        .timeout(const Duration(seconds: 20));
  } catch (_) {
    throw FriendlyException(
      'Message not sent. Check your connection and try again.',
    );
  }
}

