    'items':[{'name':'PRIVATE-PURCHASE','price':999,'qty':1}], 'totals':{'grandTotal':999},
    'unexpected':{'secret':'PRIVATE-SECRET'},
  };
  test('public status projection excludes identity address purchases totals and unknown nested fields',(){
    final source=order(), before=jsonEncode(order()); final result=verificationSnapshot(source);
    expect(result.keys.toSet(),{'orderNumber','status','payment','createdAt','trackingId'});
    final output=jsonEncode(result);expect(output, isNot(contains('PRIVATE')));expect(output,isNot(contains('+923001234567')));expect(output,isNot(contains('private@example.test')));
    expect(jsonEncode(source),before);
    expect(result['status'],'Processing');expect(result['trackingId'],'TRACK-123');
  });
  test('admin and checkout use the same allowlist without reintroducing legacy private fields',(){
    final source=order();expect(publicOrder(source),verificationSnapshot(source));
    expect(publicOrder({...source,'status':'Shipped','payment':'Paid'})['status'],'Shipped');
    expect(publicOrder(source).containsKey('customer'),isFalse);expect(publicOrder(source).containsKey('address'),isFalse);
  });
  test('malformed scalar values do not stringify and leak nested maps or arbitrary status text',(){
    final result=verificationSnapshot({'orderNumber':{'email':'PRIVATE'},'status':'PRIVATE-FIRST','payment':{'phone':'PRIVATE'},'createdAt':'PRIVATE-ADDRESS','trackingId':{'secret':'PRIVATE'}});
    expect(result,{'orderNumber':'','status':'Pending','payment':'Unpaid','createdAt':'','trackingId':''});
    expect(jsonEncode(result),isNot(contains('PRIVATE')));
  });
  test('public date and scalar limits normalize valid legacy data and reject excessive payloads',(){
    final source=order();final result=verificationSnapshot({...source,'createdAt':'2026-10-25T15:00:00+05:00','trackingId':'x'*101});
    expect(result['createdAt'],'2026-10-25T10:00:00.000Z');expect(result['trackingId'],'');
    expect(verificationSnapshot({...source,'orderNumber':'private@example.test'})['orderNumber'],'');
  });
  test('private checkout order still retains required customer and delivery details',(){
    final source=buildOrder(cart:[CartItem(productId:'fixture',name:'Fixture',qty:1,price:100)],f:CheckoutForm(firstName:'Alice',lastName:'Student',phone:'+923001234567',phoneSecondary:'',line1:'Private house',city:'Lahore',province:'Punjab',deliveryAddress:'Private delivery',notes:'Private note'),email:'alice@example.test',delivery:DeliverySettings.fromRaw({}),orderNumber:'PW-2026-123456');
    expect(source['customer']['phone'],'+923001234567');expect(source['address']['line1'],'Private house');
    expect(verificationSnapshot(source).containsKey('customer'),isFalse);
  });
}

