import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../../app/providers.dart';
import '../../../core/widgets/common.dart';
import '../../auth/domain/reference_data.dart';
import '../../auth/domain/student_profile.dart';
import '../data/admin_repository.dart';

/// Private read-only roster. Firestore rules independently restrict list/get
/// to the existing fixed administrator UID; no credentials are stored here.
class AdminStudentsScreen extends ConsumerStatefulWidget {
  const AdminStudentsScreen({super.key});

  @override
  ConsumerState<AdminStudentsScreen> createState() => _AdminStudentsState();
}

class _AdminStudentsState extends ConsumerState<AdminStudentsScreen> {
  final _students = <StudentProfile>[];
  String? _cursor;
  bool _loading = false;
  bool _hasMore = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    Future.microtask(_load);
  }

  Future<void> _load({bool refresh = false}) async {
    if (_loading || (!refresh && !_hasMore) || !ref.read(isAdminProvider)) return;
    setState(() { _loading = true; _error = null; });
    final cursor = refresh ? null : _cursor;
    try {
      if (refresh) ref.invalidate(adminStudentPageProvider(null));
      final page = await ref.read(adminStudentPageProvider(cursor).future);
      if (!mounted || !ref.read(isAdminProvider)) return;
      setState(() {
        if (refresh) _students.clear();
        _students.addAll(page.students);
        _cursor = page.nextCursor;
        _hasMore = page.nextCursor != null;
      });
    } catch (_) {
      if (mounted) setState(() => _error = 'Could not load students. Check your connection and admin access.');
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  void _details(StudentProfile p) {
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      builder: (context) => SafeArea(
        child: ListView(
          shrinkWrap: true,
          padding: const EdgeInsets.all(20),
          children: [
            Text(p.fullName, style: Theme.of(context).textTheme.titleLarge),
            const SizedBox(height: 12),
            for (final item in <(String, String?)>[
              ('Email', p.email), ('Phone', p.mobile), ('City', p.city),
              ('Professional year', ReferenceData.yearLabel(p.professionalYear)),
              ('Institution', p.institutionName),
              ('Affiliation', p.affiliationDisplay ?? 'Non-affiliated'),
              ('Roll number', p.rollNumber),
              ('Gender', ReferenceData.genders[p.gender] ?? p.gender),
            ])
              if (item.$2 != null && item.$2!.isNotEmpty)
                ListTile(title: Text(item.$1), subtitle: Text(item.$2!)),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (!ref.watch(isAdminProvider)) {
      return const Scaffold(body: Center(child: Text('Administrator access required')));
    }
    return Scaffold(
      appBar: const HTopBar(title: 'Student profiles'),
      body: RefreshIndicator(
        onRefresh: () => _load(refresh: true),
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            const Text('App student profiles · private, read only'),
            const SizedBox(height: 12),
            if (_students.isEmpty && !_loading && _error == null)
              const ListTile(title: Text('No app profiles yet'), subtitle: Text('Firebase Auth users without a saved student profile do not appear here.')),
            for (final p in _students)
              ListTile(
                leading: const Icon(Icons.person_outline),
                title: Text(p.fullName.isEmpty ? 'Student profile' : p.fullName),
                subtitle: Text('${ReferenceData.yearLabel(p.professionalYear)} · ${p.institutionName}'),
                onTap: () => _details(p),
              ),
            if (_error != null)
              ListTile(title: Text(_error!), trailing: TextButton(onPressed: _load, child: const Text('Retry'))),
            if (_loading) const Center(child: Padding(padding: EdgeInsets.all(20), child: CircularProgressIndicator())),
            if (_hasMore && !_loading && _error == null)
              TextButton(onPressed: _load, child: const Text('Load more')),
          ],
        ),
      ),
    );
  }
}

