import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/foundation.dart';

import '../../../core/errors/app_error.dart';
import '../domain/student_profile.dart';

/// Firebase Auth (same project) — credentials owned by Firebase only.
class AuthRepository {
  AuthRepository(this._auth);
  final FirebaseAuth _auth;

  Stream<User?> authChanges() => _auth.authStateChanges();
  User? get currentUser => _auth.currentUser;

  Future<User> signIn(String email, String password) async {
    try {
      final c = await _auth.signInWithEmailAndPassword(
        email: email.trim(),
        password: password,
      );
      return c.user!;
    } on FirebaseAuthException catch (e) {
      if (kDebugMode) debugPrint('signIn error: ${e.code} ${e.message}');
      throw FriendlyException(AuthErrorMapper.message(e.code), code: e.code);
    } catch (e) {
      if (kDebugMode) debugPrint('signIn unknown: $e');
      throw FriendlyException(
        'Sign-in failed. Please check your connection and try again.',
      );
    }
  }

  Future<User> createAccount(
    String email,
    String password, {
    String? displayName,
  }) async {
    try {
      final c = await _auth.createUserWithEmailAndPassword(
        email: email.trim(),
        password: password,
      );
      if (displayName != null && displayName.isNotEmpty) {
        try {
          await c.user!.updateDisplayName(displayName);
        } catch (_) {}
      }
      return c.user!;
    } on FirebaseAuthException catch (e) {
      if (kDebugMode) debugPrint('create error: ${e.code}');
      throw FriendlyException(AuthErrorMapper.message(e.code), code: e.code);
    }
  }

  Future<void> sendReset(String email) async {
    try {
      await _auth.sendPasswordResetEmail(email: email.trim());
    } on FirebaseAuthException catch (e) {
      // Do not reveal whether an account exists for 'user-not-found'.
      if (e.code == 'user-not-found') return;
      throw FriendlyException(AuthErrorMapper.message(e.code), code: e.code);
    }
  }

  Future<void> signOut() => _auth.signOut();
}

/// Student profiles in students/{uid}; production owner/admin rules published.
class StudentProfileRepository {
  StudentProfileRepository(this._db);
  final FirebaseFirestore _db;
  static const collection = 'students';

  DocumentReference<Map<String, dynamic>> _doc(String uid) =>
      _db.collection(collection).doc(uid);

  Future<StudentProfile?> fetch(String uid) async {
    final s = await _doc(uid).get();
    if (!s.exists || s.data() == null) return null;
    return StudentProfile.fromMap(uid, s.data()!);
  }

  Stream<StudentProfile?> watch(String uid) => _doc(uid).snapshots().map(
    (s) => (!s.exists || s.data() == null)
        ? null
        : StudentProfile.fromMap(uid, s.data()!),
  );

  /// Idempotent recovery: retain immutable identity and createdAt on retries.
  Future<void> create(StudentProfile p) async {
    await _db
        .runTransaction((tx) async {
          final doc = _doc(p.uid);
          final snapshot = await tx.get(doc);
          if (snapshot.exists) {
            final value = p.toWriteMap()
              ..remove('uid')
              ..remove('email')
              ..remove('role');
            tx.update(doc, {
              ...value,
              'updatedAt': FieldValue.serverTimestamp(),
            });
          } else {
            tx.set(doc, {
              ...p.toWriteMap(),
              'createdAt': FieldValue.serverTimestamp(),
              'updatedAt': FieldValue.serverTimestamp(),
            });
          }
        })
        .timeout(const Duration(seconds: 20));
  }

  /// Students may update only permitted fields (uid/email/role/createdAt are immutable).
  Future<void> update(StudentProfile p) async {
    final m = p.toWriteMap()
      ..remove('uid')
      ..remove('email')
      ..remove('role');
    await _doc(p.uid).update({...m, 'updatedAt': FieldValue.serverTimestamp()});
  }
}

test/checkout_recovery_test.dart:
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:hyzen_pharmd/app/providers.dart';
import 'dart:io';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:hyzen_pharmd/core/storage/local_store.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/features/shop/data/shop_controllers.dart';

void main() {
  late Directory temp;
  setUp(() async {
    temp = await Directory.systemTemp.createTemp('hyzen-checkout-test-');
    Hive.init(temp.path);
    await Hive.openBox<String>(Boxes.cart);
  });
  tearDown(() async { await Hive.close(); await temp.delete(recursive: true); });
  final purchase = [CartItem(productId: 'book', name: 'Book', qty: 2, price: 100, variant: 'Blue')];
  Map<String, dynamic> fullOrder(String id) => {
    'id': id, 'verifyToken': 'v_${'a' * 32}', 'orderNumber': 'PW-2026-123456',
    'createdAt': '2026-10-25T10:00:00.000Z', 'items': [], 'customer': {}, 'address': {},
    'totals': {'subtotal': 200, 'delivery': 50, 'grandTotal': 250}};
  test('outbox survives restart with original IDs and is account scoped', () async {
    await PendingCheckoutStore('alice').stage(fullOrder('original'), purchase);
    await Hive.close(); await Hive.openBox<String>(Boxes.cart);
    final restored = PendingCheckoutStore('alice').read()!;
    expect((restored['order'] as Map)['id'], 'original');
    expect((restored['cart'] as List).single['variant'], 'Blue');
    expect(PendingCheckoutStore('bob').read(), isNull);
    final retry = await PendingCheckoutStore('alice').stage(fullOrder('replacement'), []);
    expect((retry['order'] as Map)['id'], 'original');
  });
  test('acknowledged outbox remains resumable until durable cleanup completes', () async {
    final store = PendingCheckoutStore('alice');
    final record = await store.stage(fullOrder('original'), purchase);
    await store.acknowledge(record);
    await Hive.close(); await Hive.openBox<String>(Boxes.cart);
    expect(store.read()!['acknowledged'], true);
    await store.clear(); expect(store.read(), isNull);
  });
  test('corrupt pending record blocks replacement instead of risking a second order', () async {
    await Hive.box<String>(Boxes.cart).put('pending_checkout_alice', 'broken-json');
    final store = PendingCheckoutStore('alice');
    expect(store.exists, true);
    expect(store.read, throwsException);
    await expectLater(store.stage(fullOrder('replacement'), purchase), throwsException);
    expect(Hive.box<String>(Boxes.cart).get('pending_checkout_alice'), 'broken-json');
  });
  test('cart completion retains later quantities and other variants', () {
    final remaining = cartAfterPurchase([
      purchase.single.withQty(5),
      CartItem(productId: 'book', name: 'Book', qty: 1, price: 100, variant: 'Red'),
      CartItem(productId: 'pen', name: 'Pen', qty: 1, price: 20)], purchase);
    expect(remaining.map((i) => i.qty), [3, 1, 1]);
    expect(cartAfterPurchase(purchase, purchase), isEmpty);
    expect(cartAfterPurchase([], purchase), isEmpty);
  });
  final order = <String, dynamic>{'orderNumber': 'PW-2026-123456',
    'createdAt': '2026-10-25T10:00:00.000Z'};
  test('successful atomic write needs no public lookup', () async {
    await submitOrderAttempt(order, writeAtomic: () async {},
      readReceipt: () async => throw StateError('must not read'));
  });
  test('lost acknowledgement recovers same receipt without another order', () async {
    var writes = 0;
    await submitOrderAttempt(order, writeAtomic: () async { writes++; throw StateError('lost ack'); },
      readReceipt: () async => {...verificationSnapshot(order), 'status': 'Shipped'});
    expect(writes, 1);
  });
  test('missing mismatched and unavailable receipts never claim success', () async {
    for (final receipt in [null, {'orderNumber': 'PW-2026-999999'},
      {...verificationSnapshot(order), 'createdAt': '2025-01-01'}]) {
      await expectLater(submitOrderAttempt(order, writeAtomic: () async => throw StateError('offline'),
        readReceipt: () async => receipt), throwsException);
    }
    await expectLater(submitOrderAttempt(order, writeAtomic: () async => throw StateError('offline'),
      readReceipt: () async => throw StateError('offline')), throwsException);
  });
  test('history failure after acknowledgement still clears cart and reports warning', () async {
    var cleared = false;
    final saved = await finishAcknowledgedOrder(saveHistory: () async => throw StateError('disk full'),
      clearCart: () async { cleared = true; });
    expect(saved, false); expect(cleared, true);
  });
  test('cleanup failure does not turn acknowledgement into submit failure', () async {
    expect(await finishAcknowledgedOrder(saveHistory: () async {},
      clearCart: () async => throw StateError('disk error')), false);
    expect(await finishAcknowledgedOrder(saveHistory: () async {}, clearCart: () async {}), true);
  });
  test('durable cart marker prevents repeated cleanup consuming later additions', () async {
    await JsonBox(Boxes.cart).put('items_guest', {'items': purchase.map((i) => i.toMap()).toList()});
    final container = ProviderContainer(overrides: [authStateProvider.overrideWith((ref) => Stream.value(null))]);
    addTearDown(container.dispose);
    final controller = container.read(cartProvider.notifier);
    expect(container.read(cartProvider).single.qty, 2);
    await controller.completeOrder('original', purchase);
    expect(container.read(cartProvider), isEmpty);
    await JsonBox(Boxes.cart).put('items_guest', {'items': purchase.map((i) => i.withQty(4).toMap()).toList(), 'completedOrderId': 'original'});
    container.invalidate(cartProvider);
    final restored = container.read(cartProvider.notifier);
    expect(container.read(cartProvider).single.qty, 4);
    await restored.completeOrder('original', purchase);
    expect(container.read(cartProvider).single.qty, 4);
  });

  test('malformed persisted totals block checkout rather than crashing the screen', () async {
    await JsonBox(Boxes.cart).put('pending_checkout_alice', {
      'order': {...fullOrder('original'), 'totals': {'subtotal': 'bad', 'delivery': 0, 'grandTotal': 0}},
      'cart': purchase.map((i) => i.toMap()).toList()});
    expect(PendingCheckoutStore('alice').read, throwsException);
  });

}
